INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(48811, 'Numbers 35:26', 'Numbers', 35, 26, 'خو که چېرې په قتل باندې تورن کس د پناه اخیستلو ښار چې ورته تښتېدلی ؤ پرېږدي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers35_verse_26.mp3', '', 1761754199, 1761754199),
(48812, 'Numbers 35:27', 'Numbers', 35, 27, 'او د وژل شوي کس ډېر نژدې خپلوان هغه پیدا کړي او ویې وژني، نو دغه بدل اخیستنه قتل نه دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers35_verse_27.mp3', '', 1761754199, 1761754199),
(48813, 'Numbers 35:28', 'Numbers', 35, 28, 'په قتل باندې تورن کس باید د لوی کاهن تر مړینې پورې د پناه اخیستلو په ښار کې پاتې شي، خو له هغې وروسته کولای شي چې خپل کور ته ستون شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers35_verse_28.mp3', '', 1761754199, 1761754199),
(48814, 'Numbers 35:29', 'Numbers', 35, 29, 'دا قوانین به په تاسو او ستاسو په اولادې باندې چې په هرځای کې اوسیږي عملي کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers35_verse_29.mp3', '', 1761754199, 1761754199),
(48815, 'Numbers 35:30', 'Numbers', 35, 30, 'په قتل باندې تورن کس باید یوازې په داسې حال کې مجرم وګڼل شي او ووژل شي چې دوه یا د هغه څخه زیات شاهدان شاهدي ورکړي. د قتل د تور د ثابتولو دپاره د یو کس شاهدي ورکول بس نه دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers35_verse_30.mp3', '', 1761754199, 1761754199),
(48816, 'Numbers 35:31', 'Numbers', 35, 31, 'قاتل باید ووژل شي. هغه د پیسو په ورکولو سره د دې سزا څخه نه شي خلاصېدلی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers35_verse_31.mp3', '', 1761754199, 1761754199),
(48817, 'Numbers 35:32', 'Numbers', 35, 32, 'که چېرې څوک د پناه اخیستلو ښار ته تښتېدلی وي، نو هغه مه پرېږدئ چې د لوی کاهن د مړینې څخه مخکې خپل کور ته د بېرته ستنېدلو په خاطر بیه ادا کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers35_verse_32.mp3', '', 1761754199, 1761754199),
(48818, 'Exodus 20:1', 'Exodus', 20, 1, 'خدای خبرې وکړې او د هغه خبرې دا وې:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus20_verse_1.mp3', '', 1761754199, 1761754199),
(48819, 'Exodus 20:2', 'Exodus', 20, 2, '«زه ستاسو څښتن خدای یم او تاسو مې له مصر څخه چې په کې غلامان وئ، راوویستلئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus20_verse_2.mp3', '', 1761754199, 1761754199),
(48820, 'Exodus 20:3', 'Exodus', 20, 3, 'زما څخه پرته د بل خدای عبادت مه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus20_verse_3.mp3', '', 1761754199, 1761754199),
(48821, 'Exodus 20:4', 'Exodus', 20, 4, 'د خپلو ځانونو دپاره د هېڅ شي په شکل چې هغه په اسمان کې یا په ځمکه باندې یا د ځمکې لاندې په اوبو کې وي، بتان مه جوړوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus20_verse_4.mp3', '', 1761754199, 1761754199),
(48822, 'Exodus 20:5', 'Exodus', 20, 5, 'هېڅ بت ته سجده یا عبادت مه کوئ، ځکه چې زه ستاسو څښتن خدای یو غیرتي خدای یم. څوک چې زما څخه کرکه کوي، زه به هغوی او د هغوی اولادې ته تر درېم او څلورم نسله پورې سزا ورکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus20_verse_5.mp3', '', 1761754199, 1761754199),
(48823, 'Exodus 20:6', 'Exodus', 20, 6, 'خو زه د هغو زرګونو نسلونو سره چې زما سره مینه کوي او زما امرونو ته غاړه ږدي، مینه کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus20_verse_6.mp3', '', 1761754199, 1761754199),
(48824, 'Exodus 20:7', 'Exodus', 20, 7, 'زما نوم د بدو مقصدونو دپاره مه کاروئ، ځکه چې زه ستاسو څښتن خدای به هغه چاته سزا ورکړم چې زما نوم په غلطه وکاروي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus20_verse_7.mp3', '', 1761754199, 1761754199),
(48825, 'Exodus 20:8', 'Exodus', 20, 8, 'د سبت ورځ ولمانځئ او هغه سپېڅلې وګڼئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus20_verse_8.mp3', '', 1761754199, 1761754199),
(48826, 'Exodus 20:9', 'Exodus', 20, 9, 'تاسو د کار کولو دپاره شپږ ورځې لرئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus20_verse_9.mp3', '', 1761754199, 1761754199),
(48827, 'Exodus 20:10', 'Exodus', 20, 10, 'خو اوومه ورځ د ارام کولو ورځ ده چې څښتن خدای ته وقف شوې ده. په دې ورځ به تاسو هېڅ کار نه کوئ، نه تاسو، نه ستاسو زامن یا لورګانې، نه غلامان، نه ستاسو حیوانات، نه هغه پردي خلک چې ستاسو په وطن کې اوسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus20_verse_10.mp3', '', 1761754199, 1761754199),
(48828, 'Exodus 20:11', 'Exodus', 20, 11, 'ما څښتن په شپږو ورځو کې ځمکه، اسمانونه، بحیرې او هرڅه چې په هغو کې دي جوړ کړل، خو په اوومه ورځ مې ارام وکړ. ځکه چې ما سبت ته برکت ورکړ او هغه مې سپېڅلی کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus20_verse_11.mp3', '', 1761754199, 1761754199),
(48829, 'Exodus 20:12', 'Exodus', 20, 12, 'د خپل مور او پلار عزت کوئ، ترڅو تاسو په هغه خاوره کې چې زه یې درکوم زیات عمر ولرئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus20_verse_12.mp3', '', 1761754199, 1761754199),
(48830, 'Exodus 20:13', 'Exodus', 20, 13, 'قتل مه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus20_verse_13.mp3', '', 1761754199, 1761754199),
(48831, 'Exodus 20:14', 'Exodus', 20, 14, 'زنا مه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus20_verse_14.mp3', '', 1761754199, 1761754199),
(48832, 'Exodus 20:15', 'Exodus', 20, 15, 'غلا مه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus20_verse_15.mp3', '', 1761754199, 1761754199),
(48833, 'Exodus 20:16', 'Exodus', 20, 16, 'د هېچا په خلاف د دروغو شهادت مه ورکوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus20_verse_16.mp3', '', 1761754199, 1761754199),
(48834, 'Exodus 20:17', 'Exodus', 20, 17, 'د خپل ګاونډي د کور تمه مه کوئ. د هغه د ښځې، غلامانو، غویانو، خرو یا هرڅه چې هغه یې لري، تمه مه کوئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus20_verse_17.mp3', '', 1761754199, 1761754199),
(48835, 'Exodus 20:18', 'Exodus', 20, 18, 'کله چې ټولو خلکو د تندر او سرني غږ واورېد او برېښنا او هغه غر یې ولیده چې لوګی ورڅخه پورته کېده، نو هغوی د وېرې له لاسه ولړزېدل او لېرې ودرېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus20_verse_18.mp3', '', 1761754199, 1761754199),
(48836, 'Exodus 20:19', 'Exodus', 20, 19, 'هغوی موسی ته وویل: «که چېرې ته زمونږ سره خبرې وکړې، غوږ به درته ونیسو. خو مونږ وېرېږو چې که چېرې خدای زمونږ سره خبرې وکړي، نو مړه به شو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus20_verse_19.mp3', '', 1761754199, 1761754199),
(48837, 'Exodus 20:20', 'Exodus', 20, 20, 'موسی خلکو ته وویل: «مه وېرېږئ. خدای ستاسو د ازمایلو دپاره راغلی دی، ترڅو د هغه وېره درسره وي او ګناه ونه کړئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus20_verse_20.mp3', '', 1761754199, 1761754199),
(48838, 'Exodus 20:21', 'Exodus', 20, 21, 'خو خلک په یوې لېرې فاصلې کې ودرېدل او موسی هغې تورې تیارې ته ورنژدې شو چې خدای په کې ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus20_verse_21.mp3', '', 1761754199, 1761754199),
(48839, 'Exodus 20:22', 'Exodus', 20, 22, 'بیا څښتن موسی ته وویل: «اسراییلیانو ته داسې ووایه: تاسو په خپله لیدلي دي چې ما څنګه تاسو سره د اسمان څخه خبرې وکړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus20_verse_22.mp3', '', 1761754199, 1761754199),
(48840, 'Exodus 20:23', 'Exodus', 20, 23, 'د ځانونو دپاره د سرو او سپینو زرو خدایان مه جوړوئ چې زما په ځای د هغه عبادت وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus20_verse_23.mp3', '', 1761754199, 1761754199),
(48841, 'Exodus 20:24', 'Exodus', 20, 24, 'زما دپاره د خاورو څخه د قربانۍ ځای جوړ کړئ او په هغه باندې د خپلو رمو او پادو څخه حیوانات قرباني او خپلې سوځېدونکې او د سلامتۍ نذرانې وړاندې کړئ. هرځای چې زه یې ستاسو دپاره ټاکم چې زما عبادت په کې وکړئ، زه به هلته درشم او تاسو ته به برکت درکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus20_verse_24.mp3', '', 1761754199, 1761754199),
(48842, 'Exodus 20:25', 'Exodus', 20, 25, 'که چېرې تاسو زما دپاره د تیږو څخه د قربانۍ ځای جوړوئ، نو د توږل شویو تیږو څخه یې مه جوړوئ، ځکه که چېرې په هغو باندې د کوم سامان څخه کار واخلئ، هغه به ناپاک کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus20_verse_25.mp3', '', 1761754199, 1761754199),
(48843, 'Exodus 20:26', 'Exodus', 20, 26, 'زما د قربانۍ ځای ته په زینه باندې مه ورخېژئ، ترڅو په هغې باندې ستاسو د شرم ځای ښکاره نه شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus20_verse_26.mp3', '', 1761754199, 1761754199),
(48844, 'Psalms 29:1', 'Psalms', 29, 1, 'د څښتن ستاینه وکړئ د اسمان مخلوقه ووایئ چې څومره ډک دی د جلال نه د څښتن نوم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms29_verse_1.mp3', '', 1761754199, 1761754199),
(48845, 'Psalms 29:2', 'Psalms', 29, 2, 'د څښتن عبادت وکړئ د هغه په سپېڅلتوب او شان شوکت کې کړئ څښتن ته عبادت په سپېڅلې توګه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms29_verse_2.mp3', '', 1761754199, 1761754199),
(48846, 'Psalms 29:3', 'Psalms', 29, 3, 'په دریابونو اورېدلی شي اواز د څښتن جلالي خدای کړي خبرې لکه تندر په ټولو دریابونو اورېدی شي اواز د هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms29_verse_3.mp3', '', 1761754199, 1761754199),
(48847, 'Psalms 29:4', 'Psalms', 29, 4, 'زورور دی د څښتن اواز ډک دی له جلاله د څښتن اواز', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms29_verse_4.mp3', '', 1761754199, 1761754199),
(48848, 'Psalms 29:5', 'Psalms', 29, 5, 'چې څښتن کاندي خبرې نو اواز یې ماتوي د سبر ونې حتی دا چې ماتوي هم د لبنان د سبر ونې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms29_verse_5.mp3', '', 1761754199, 1761754199),
(48849, 'Psalms 29:6', 'Psalms', 29, 6, 'لړزوي هغه ټول غرونه د لبنان وهي څرنګه ټوپونه چې خوسی د حرمون غر په دا ډول خوځېدل کړي لکه د ځوان وحشي غویي د ټوپونو په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms29_verse_6.mp3', '', 1761754199, 1761754199),
(48850, 'Psalms 29:7', 'Psalms', 29, 7, 'ځلېدونکې برېښنا جوړه له اوازه د څښتن شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms29_verse_7.mp3', '', 1761754199, 1761754199),
(48851, 'Psalms 29:8', 'Psalms', 29, 8, 'د څښتن اواز دښته په لړزان راولي ده په لړزان د قادش دښته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms29_verse_8.mp3', '', 1761754199, 1761754199),
(48852, 'Psalms 29:9', 'Psalms', 29, 9, 'د څښتن په اواز کږوي د څېړۍ ونې او د ونو څخه پاڼې رژوي نو د خدای په کور کې هر یو چیغې وهي: «وي دې جلال څښتن ته»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms29_verse_9.mp3', '', 1761754199, 1761754199),
(48853, 'Psalms 29:10', 'Psalms', 29, 10, 'حکم چلوي څښتن سېلاب باندې وي هغه پاچا به تر ابده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms29_verse_10.mp3', '', 1761754199, 1761754199),
(48854, 'Psalms 29:11', 'Psalms', 29, 11, 'ورکوي څښتن ولس خپل ته قوت ورکوي ورته د سولې برکت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms29_verse_11.mp3', '', 1761754199, 1761754199),
(48855, 'Judges 1:1', 'Judges', 1, 1, 'د یوشع د مړینې څخه وروسته د اسراییلو قوم د څښتن څخه پوښتنه وکړه: «زمونږ کومه قبیله به لومړی لاړه شي او په کنعانیانو باندې به حمله وکړي؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges1_verse_1.mp3', '', 1761754199, 1761754199),
(48856, 'Judges 1:2', 'Judges', 1, 2, 'څښتن په ځواب کې وویل: «لومړی به د یهودا قبیله لاړه شي. زه به هغوی ته د کنعانیانو خاوره په لاس ورکړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges1_verse_2.mp3', '', 1761754199, 1761754199),
(48857, 'Judges 1:3', 'Judges', 1, 3, 'د یهودا خلکو د شمعون خلکو ته وویل: «زمونږ سره هغې سیمې ته لاړ شئ چې مونږ ته راکړل شوې ده، ترڅو په ګډه د کنعانیانو سره جګړه وکړو. بیا به مونږ ستاسو سره مرسته وکړو چې خپله سیمه ونیسئ.» نو د شمعون', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges1_verse_3.mp3', '', 1761754199, 1761754199),
(48858, 'Judges 1:4', 'Judges', 1, 4, 'او یهودا قبیلې سره یوځای جګړې ته لاړلې. څښتن هغوی په کنعانیانو او فرزیانو باندې بریالي کړل او هغوی په بازق کې د دښمنانو لس زره تنه ووژل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges1_verse_4.mp3', '', 1761754199, 1761754199),
(48859, 'Judges 1:5', 'Judges', 1, 5, 'هلته دوی ادوني بازق پیدا کړ او د هغه سره یې جګړه وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges1_verse_5.mp3', '', 1761754199, 1761754199),
(48860, 'Judges 1:6', 'Judges', 1, 6, 'ادوني بازق وتښتېد. خو هغوی ورپسې شول، هغه یې ونیوه او د هغه د پښو او لاسونو غټې ګوتې یې غوڅې کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges1_verse_6.mp3', '', 1761754199, 1761754199),
(48861, 'Judges 1:7', 'Judges', 1, 7, 'ادوني بازق وویل: «اویا پاچاهانو چې د هغوی د پښو او لاسونو غټې ګوتې غوڅې شوې وې، زما د دسترخوان پاتې شونې یې خوړل. اوس خدای زما څخه د هغوی بدله واخیستله.» بیا هغوی هغه اورشلیم ته راوست او هلته مړ شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges1_verse_7.mp3', '', 1761754199, 1761754199),
(48862, 'Judges 1:8', 'Judges', 1, 8, 'د یهودا خلکو په اورشلیم باندې حمله وکړه او هغه یې ونیوه. د هغه ښار خلک یې ووژل او ښار ته یې اور واچاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges1_verse_8.mp3', '', 1761754199, 1761754199),
(48863, 'Judges 1:9', 'Judges', 1, 9, 'له هغې وروسته هغوی لاړل چې د کنعانیانو سره چې په غرنۍ سیمه، د غرونو په لوېدیځو لمنو او جنوبي دښته کې اوسېدل، جګړه وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges1_verse_9.mp3', '', 1761754199, 1761754199),
(48864, 'Judges 1:10', 'Judges', 1, 10, 'هغوی د کنعانیانو په وړاندې چې په حبرون کې اوسېدل، راپورته شول. (حبرون پخوا د قریت اربع په نوم یادېده.) هلته هغوی د شیشای، اخیمان او تلمای طایفو ته ماتې ورکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges1_verse_10.mp3', '', 1761754199, 1761754199),
(48865, 'Judges 1:11', 'Judges', 1, 11, 'د هغه ځای څخه د یهودا کسان لاړل چې په دبیر باندې حمله وکړي. (دبیر په هغه وخت کې د قریت سفر په نوم یادېده.)', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges1_verse_11.mp3', '', 1761754199, 1761754199),
(48866, 'Judges 1:12', 'Judges', 1, 12, 'د هغوی یو کس چې کالیب نومېده وویل: «هرچا چې قریت سفر فتح کړ، زه به خپله لور عکسه هغه ته په نکاح ورکړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges1_verse_12.mp3', '', 1761754199, 1761754199),
(48867, 'Judges 1:13', 'Judges', 1, 13, 'د کالیب د کشر ورور قناز زوی عتني ییل هغه ښار ونیوه، نو کالیب خپله لور هغه ته په نکاح ورکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges1_verse_13.mp3', '', 1761754199, 1761754199),
(48868, 'Judges 1:14', 'Judges', 1, 14, 'د واده په ورځ عتني ییل عکسه وهڅوله چې د خپل پلار څخه یو پټی وغواړي. کله چې عکسه د خپل خره څخه راښکته شوه، کالیب ورڅخه پوښتنه وکړه: «څه غواړې؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges1_verse_14.mp3', '', 1761754199, 1761754199),
(48869, 'Judges 1:15', 'Judges', 1, 15, 'هغې په ځواب کې وویل: «زه د اوبو یو څو چینې غواړم. هغه ځمکه چې تا راته راکړې ده هغه په جنوبي دښته کې ده.» نو کالیب هغې ته پورتنۍ او ښکتنۍ چینې ورکړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges1_verse_15.mp3', '', 1761754199, 1761754199),
(48870, 'Judges 1:16', 'Judges', 1, 16, 'د موسی د خسر اولاده چې قینیان وو د اریحا یعنې د خرما د ونو د ښار څخه د یهودا د خلکو سره د یهودا جنوبي دښتې ته چې عراد ته نژدې پرته وه، لاړل. هلته هغوی د عمالیقیانو سره اوسېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges1_verse_16.mp3', '', 1761754199, 1761754199),
(48871, 'Judges 1:17', 'Judges', 1, 17, 'د یهودا خلک د شمعون د خلکو سره لاړل او په ګډه یې په کنعانیانو باندې چې د صفت په ښار کې اوسېدل، حمله وکړه. ښار یې په پوره توګه وران کړ، نو له دې امله یې د هغه نوم حرما کېښود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges1_verse_17.mp3', '', 1761754199, 1761754199),
(48872, 'Judges 1:20', 'Judges', 1, 20, 'لکه څنګه چې موسی وعده کړې وه، د حبرون ښار کالیب ته ورکړل شو او کالیب هغه درې طایفې چې د عناق د اولادې څخه وې، وشړلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges1_verse_20.mp3', '', 1761754199, 1761754199),
(48873, 'Judges 1:21', 'Judges', 1, 21, 'خو د بنیامین د قبیلې خلکو یبوسیان چې په اورشلیم کې اوسېدل، ونه شړل او د هغه وخت څخه تر اوسه پورې یبوسیان د بنیامین د خلکو سره هلته اوسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges1_verse_21.mp3', '', 1761754199, 1761754199),
(48874, 'Judges 1:24', 'Judges', 1, 24, 'او هغوی یو سړی ولیده چې د ښار څخه راروان ؤ او دوی ورته وویل: «که چېرې مونږ ته د ښار د ننوتلو لار وښایې، نو مونږ به تاته زیان ونه رسوو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges1_verse_24.mp3', '', 1761754199, 1761754199),
(48875, 'Judges 1:25', 'Judges', 1, 25, 'نو هغه سړي ورته لار وروښودله او د افرایم او منسي خلک لاړل او د ښار ټول خلک یې ووژل، خو هغه سړی او د هغه ټوله کورنۍ یې پرېښودله چې لاړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges1_verse_25.mp3', '', 1761754199, 1761754199),
(48876, 'Judges 1:26', 'Judges', 1, 26, 'بیا هغه سړی د حیتیانو خاورې ته لاړ، هلته یې یو ښار ودان کړ او په هغه باندې یې د لوز نوم کېښود چې تر اوسه پورې په همدې نوم یادیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges1_verse_26.mp3', '', 1761754199, 1761754199),
(48877, 'Judges 1:27', 'Judges', 1, 27, 'د منسي قبیلې د بیت شان، تعنک، دور، یبلعام، مجدو او د هغو د شاوخوا کلیو خلک ونه شړل. نو کنعانیانو هلته اوسېدلو ته دوام ورکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges1_verse_27.mp3', '', 1761754199, 1761754199),
(48878, 'Judges 1:28', 'Judges', 1, 28, 'کله چې اسراییلیان قوي شول، نو کنعانیان یې په سختو کارونو باندې مجبورول، خو بیاهم هغوی یې بیخي ونه شړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges1_verse_28.mp3', '', 1761754199, 1761754199),
(48879, 'Judges 1:29', 'Judges', 1, 29, 'د افرایم قبیلې هم هغه کنعانیان ونه شړل چې د جازر اوسېدونکي وو، نو هغوی د افرایم د قبیلې په منځ کې هلته په جازر کې پاتې شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges1_verse_29.mp3', '', 1761754199, 1761754199),
(48880, 'Judges 1:30', 'Judges', 1, 30, 'د زبولون قبیلې هم د قطرون او نهلول اوسېدونکي ونه شړل، نو کنعانیان د هغوی په منځ کې هلته اوسېدل او مجبور وو چې د هغوی دپاره سخت کار وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges1_verse_30.mp3', '', 1761754199, 1761754199),
(48881, 'Judges 1:31', 'Judges', 1, 31, 'همدارنګه د اشیر قبیلې د عکو، صیدون، احلب، اکزیب، حلبه، عفیق او رحوب اوسېدونکي ونه شړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges1_verse_31.mp3', '', 1761754199, 1761754199),
(48882, 'Judges 1:32', 'Judges', 1, 32, 'اشیریان د ځایي کنعانیانو په منځ کې اوسېدل، ځکه چې هغوی یې ونه شړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges1_verse_32.mp3', '', 1761754199, 1761754199),
(48883, 'Judges 1:33', 'Judges', 1, 33, 'د نفتالي قبیلې هم د بیت شمس او بیت عنات اوسېدونکي ونه شړل. نفتالیان د ځایي کنعانیانو په منځ کې اوسېدل. خو هغوی د دې دوو ځایونو اوسېدونکي په سخت کار کولو مجبورول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges1_verse_33.mp3', '', 1761754199, 1761754199),
(48884, 'Judges 1:34', 'Judges', 1, 34, 'اموریانو د دان د قبیلې خلک مجبور کړل چې غرنۍ سیمې ته لاړ شي او هغوی یې نه پرېښودل چې درې ته راښکته شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges1_verse_34.mp3', '', 1761754199, 1761754199),
(48885, 'Judges 1:35', 'Judges', 1, 35, 'اموریانو په ایالون، شعلبیم او د حارس په غره کې اوسېدلو ته دوام ورکړ، خو د افرایم او منسي قبیلو هغوی تر خپلې واکمنۍ لاندې ساتل او په سخت کار کولو یې مجبورول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges1_verse_35.mp3', '', 1761754199, 1761754199),
(48886, 'Judges 1:36', 'Judges', 1, 36, 'د اموریانو سرحد د عقربیم د غاښي څخه نیولې تر سالع او غرنۍ سیمې پورې رسېدلی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges1_verse_36.mp3', '', 1761754199, 1761754199),
(48887, 'Exodus 17:1', 'Exodus', 17, 1, 'د اسراییلو ټول قوم د سین دښته پرېښودله او د څښتن په حکم یې د یو ځای څخه بل ځای ته کډه کوله. هغوی په رفیدیم کې خېمې ودرولې، خو هلته د قوم دپاره د څښلو اوبه نه وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus17_verse_1.mp3', '', 1761754199, 1761754199),
(48888, 'Exodus 17:2', 'Exodus', 17, 2, 'نو هغوی موسی ته شکایت وکړ او ورته یې وویل: «مونږ ته د څښلو دپاره اوبه راکړه.» موسی په ځواب کې وویل: «تاسو ولې شکایت کوئ؟ تاسو ولې څښتن ازمایئ؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus17_verse_2.mp3', '', 1761754199, 1761754199),
(48889, 'Exodus 17:3', 'Exodus', 17, 3, 'خو خلک ډېر تږي وو او په موسی باندې غورېدل. هغوی وویل: «تا مونږ ولې د مصر څخه راوویستلو؟ ایا د دې دپاره چې مونږ د خپلو ماشومانو او حیواناتو سره له تندې مړه کړې؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus17_verse_3.mp3', '', 1761754199, 1761754199),
(48890, 'Exodus 17:4', 'Exodus', 17, 4, 'موسی څښتن ته زارۍ وکړې او ویې ویل: «زه د دې خلکو سره څه وکړم؟ نژدې دی چې دوی مې سنګسار کړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus17_verse_4.mp3', '', 1761754199, 1761754199),
(48891, 'Exodus 17:5', 'Exodus', 17, 5, 'څښتن موسی ته وویل: «د اسراییلو ځینې مشران د ځان سره بوځه او د خلکو په مخکې ځه. د ځان سره هغه امسا یوسه په کومې چې تا د نیل سیند وهلی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus17_verse_5.mp3', '', 1761754199, 1761754199),
(48892, 'Exodus 17:6', 'Exodus', 17, 6, 'زه به د سینا د غره سره په یو ګټ باندې ستا په مخکې ودرېږم. ته هغه ګټ ووهه او خلکو ته به د څښلو دپاره له هغه څخه اوبه جاري شي.» نو موسی د اسراییلو د مشرانو په مخکې همداسې وکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus17_verse_6.mp3', '', 1761754199, 1761754199),
(48893, 'Exodus 17:7', 'Exodus', 17, 7, 'او هغه د دې ځای نوم مسا او مریبه کېښود، ځکه چې اسراییلیانو شکایت وکړ او څښتن یې وازمایلو او ویې ویل: «ایا څښتن زمونږ په منځ کې دی او که نه؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus17_verse_7.mp3', '', 1761754199, 1761754199),
(48894, 'Exodus 17:8', 'Exodus', 17, 8, 'عمالیقیان رفیدیم ته راغلل او په اسراییلیانو باندې یې حمله وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus17_verse_8.mp3', '', 1761754199, 1761754199),
(48895, 'Exodus 17:9', 'Exodus', 17, 9, 'موسی یوشع ته وویل: «زمونږ د خلکو څخه یو څو تنه غوره کړه او لاړ شه د عمالیقیانو سره جګړه وکړه. زه به سبا د غونډۍ په سر ودرېږم او د خدای امسا به زما په لاسونو کې وي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus17_verse_9.mp3', '', 1761754199, 1761754199),
(48896, 'Exodus 17:10', 'Exodus', 17, 10, 'څنګه چې موسی حکم کړی ؤ، یوشع د عمالیقیانو سره جګړه وکړه او موسی، هارون او حور د غونډۍ سرته لاړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus17_verse_10.mp3', '', 1761754199, 1761754199),
(48897, 'Exodus 17:11', 'Exodus', 17, 11, 'ترڅو پورې چې د موسی لاسونه پورته وو، اسراییلیان بریالي کېدل. خو کله چې هغه خپل لاسونه ښکته کول، نو عمالیقیان به بریالي کېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus17_verse_11.mp3', '', 1761754199, 1761754199),
(48898, 'Exodus 17:12', 'Exodus', 17, 12, 'کله چې د موسی لاسونه ستړي شول، نو هارون او حور یوه تیږه راوړه او موسی یې په هغې باندې کښېناوه. هغوی د موسی دواړو خواو ته ودرېدل او د لاسونه یې پورته ونیول، نو د هغه لاسونه د لمر تر پرېوتلو پورې پورته پاتې شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus17_verse_12.mp3', '', 1761754199, 1761754199),
(48899, 'Exodus 17:13', 'Exodus', 17, 13, 'په دې ډول یوشع عمالیقیانو ته په پوره توګه ماتې ورکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus17_verse_13.mp3', '', 1761754199, 1761754199),
(48900, 'Exodus 17:14', 'Exodus', 17, 14, 'بیا څښتن موسی ته وویل: «د دې بري بیان په یو کتاب کې ولیکه، ترڅو هغه یو یادګار پاتې شي. یوشع ته ووایه چې زه به عمالیقیان په بپشړه توګه تباه کړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus17_verse_14.mp3', '', 1761754199, 1761754199),
(48901, 'Exodus 17:15', 'Exodus', 17, 15, 'موسی د قربانۍ ځای جوړ کړ او دا نوم یې ورباندې کېښود «څښتن زما د بریالیتوب بیرغ دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus17_verse_15.mp3', '', 1761754199, 1761754199),
(48902, 'Exodus 17:16', 'Exodus', 17, 16, 'هغه وویل: «د څښتن بیرغ پورته ونیسئ! څښتن به د تل دپاره د عمالیقیانو په ضد جګړې ته دوام ورکړي!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus17_verse_16.mp3', '', 1761754199, 1761754199),
(48903, 'Jeremiah 29:1', 'Jeremiah', 29, 1, 'دا د هغه خط متن دے کوم چې يرمياه پېغمبر د يروشلم نه بابل ته هغه مشرانو او اِمامانو، پېغمبرانو، او نورو ټولو خلقو ته څوک چې نبوکدنضر بادشاه د يروشلم نه بابل ته جلاوطن کړى وُو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah29_verse_1.mp3', '', 1761754199, 1761754199),
(48904, 'Jeremiah 29:2', 'Jeremiah', 29, 2, 'هغۀ دا د هغه وخت نه وروستو وليکلو کله چې يهوياکين بادشاه، د هغۀ مور مَلِکه، د دربار خصيان آفسران، د يهوداه او يروشلم مشران، ماهِر کسان او کاريګران د يروشليم نه شړلى وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah29_verse_2.mp3', '', 1761754199, 1761754199),
(48905, 'Jeremiah 29:3', 'Jeremiah', 29, 3, 'هغۀ هغه خط د اِلعاسه د سافن زوئ او ګمرياه د خِلقياه زوئ په لاس ولېږلو، کوم چې د يهوداه بادشاه صدقياه د بابل نبوکدنضر له ولېږلو. په هغې کښې دا ليکلے شوى وُو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah29_verse_3.mp3', '', 1761754199, 1761754199),
(48906, 'Jeremiah 29:4', 'Jeremiah', 29, 4, '”مالِک خُدائ ربُ الافواج، د بنى اِسرائيلو خُدائ پاک هغه ټولو خلقو ته فرمائى کوم چې ما مالِک خُدائ هغوئ د يروشلم نه بابل ته قېديان بوتلل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah29_verse_4.mp3', '', 1761754199, 1761754199),
(48907, 'Jeremiah 29:5', 'Jeremiah', 29, 5, 'خپل ځان له په بابل کښې کورونه جوړ کړئ او په هغې کښې اوسېږئ. باغونه وکَرئ او د هغې نه خوراک کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah29_verse_5.mp3', '', 1761754199, 1761754199),
(48908, 'Jeremiah 29:6', 'Jeremiah', 29, 6, 'تاسو ودونه وکړئ چې زامن او لوڼه مو پېدا شى. نو دغه شان بيا خپل زامن او لوڼه هم وادۀ کړئ چې د هغوئ هم بچى پېدا شى. تاسو په شمېر کښې زيات شئ نه چې کم شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah29_verse_6.mp3', '', 1761754199, 1761754199),
(48909, 'Jeremiah 29:7', 'Jeremiah', 29, 7, 'کوم ښار ته چې ما تاسو جلاوطن کړى يئ د دغه ښار خير غواړئ. او مالِک خُدائ ته د هغې دپاره دُعا کوئ، ځکه کۀ چرې په هغې کښې خير وى، نو تاسو به هم په خير يئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah29_verse_7.mp3', '', 1761754199, 1761754199),
(48910, 'Jeremiah 29:8', 'Jeremiah', 29, 8, 'مالِک خُدائ، ربُ الافواج د بنى اِسرائيلو خُدائ پاک تاسو ته فرمائى چې، خبردار، ستاسو په مينځ کښې چې کوم نبيان او فالبين اوسيږى چې هغوئ تاسو دوکه نۀ کړى. د هغوئ خوبونو ته توجو مۀ ورکوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah29_verse_8.mp3', '', 1761754199, 1761754199);